public static MwmsProcessCreateTagCountingJournalLine Construct(Name thisName = staticMethodStr(TFMConstants, CreateTagCountingJournalLine), AddUpdate _addOrUpdate = AddUpdate::Add)
{
    return new MwmsProcessCreateTagCountingJournalLine(thisName, _addOrUpdate);
}

protected void new(Name _processName = staticMethodStr(TFMConstants, CreateTagCountingJournalLine), AddUpdate _addOrUpdate = AddUpdate::Add)
{
    processName = _processName;
    MwmsLogicBlockCreateTagCountingJournalLicensePlateLine     LPBlock = MwmsLogicBlockCreateTagCountingJournalLicensePlateLine::Construct();
    MwmsLogicBlockCreateTagCountingJournalLine                 itemBlock           = MwmsLogicBlockCreateTagCountingJournalLine::Construct();
    itemBlock.parmCreateOrUpdate(_addOrUpdate);
    LPBlock.parmCreateOrUpdate(_addOrUpdate);
    super();

    MwmsProcessCreateTransferJournalLine::addBlocksForHandlingLicenseAndItems(this, itemBlock, LPBlock);
}
